class Vault:                              # the module exports only this name (__all__)
    def __init__(self, store, policy):
        self._store = store               # private by convention, not by enforcement
        self._policy = policy
    def read(self, who, item_id):
        if not self._policy.allows(who, item_id):
            raise PermissionError(item_id)      # decision and access in one call
        return self._store[item_id]              # the store itself never escapes
